// Normalize GitHub push or manual webhook into branch_name.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  // Manual webhook body: { branch: "master" } or { ref: "refs/heads/master" }
  let ref = j.body?.ref || j.ref || (j.body?.branch ? `refs/heads/${j.body.branch}` : null);
  if (!ref && j.body?.branch_name) ref = `refs/heads/${j.body.branch_name}`;
  // Default to master for bare webhook pings
  if (!ref && (j.headers || j.query)) ref = "refs/heads/master";
  if (!ref || !String(ref).startsWith("refs/heads/")) continue;
  item.json.branch_name = String(ref).split("refs/heads/")[1];
  const staticData = $getWorkflowStaticData("global");
  staticData.branch_name = item.json.branch_name;
  // commit message for filter
  item.json.head_commit_message = j.body?.head_commit?.message || j.head_commit?.message || j.body?.message || "";
  out.push(item);
}
return out.length ? out : [{ json: { branch_name: "master", head_commit_message: "manual" } }];

const data = $input.first().json;
const out = (data.stdout || "") + "\n" + (data.stderr || "");
if (!out.includes("::DOCVAT_BUILD_DONE::")) {
  throw new Error("Build sidecar finished without ::DOCVAT_BUILD_DONE:: marker (false success blocked)");
}
const m = out.match(/::DOCVAT_VERSION::(v[\d.]+)/);
const done = out.match(/::DOCVAT_BUILD_DONE::(v[\d.]+)/);
data.app_version = (done && done[1]) || (m && m[1]) || "desconocida";
data.build_ok = true;
return data;

